@php $fields=match($module){'entites'=>['name'=>'Nom','slug'=>'Identifiant URL','type'=>'Type','country'=>'Pays','sector'=>'Secteur','summary'=>'Résumé','description'=>'Description','website'=>'Site web'],'projets'=>['group_entity_id'=>'Entité','title'=>'Titre','category'=>'Catégorie','location'=>'Localisation','status'=>'Statut','start_date'=>'Date de début','end_date'=>'Date de fin','budget'=>'Budget','currency'=>'Devise','description'=>'Description'],default=>['group_entity_id'=>'Entité','name'=>'Nom','kind'=>'Type d’actif','location'=>'Localisation','reference'=>'Référence','status'=>'Statut','notes'=>'Notes']}; @endphp
<div class="row g-3">@foreach($fields as $field=>$label)<div class="col-md-{{ in_array($field,['description','summary','notes']) ? '12' : '6' }}"><label class="form-label fw-semibold" for="{{ $field }}-{{ $item?->id ?? 'new' }}">{{ $label }}</label>
@if($field==='group_entity_id')<select class="form-select" name="{{ $field }}" id="{{ $field }}-{{ $item?->id ?? 'new' }}" required><option value="">Sélectionner</option>@foreach($entities as $entity)<option value="{{ $entity->id }}" @selected(($item?->$field ?? null)==$entity->id)>{{ $entity->name }}</option>@endforeach</select>
@elseif(in_array($field,['description','summary','notes']))<textarea class="form-control" name="{{ $field }}" id="{{ $field }}-{{ $item?->id ?? 'new' }}" rows="3">{{ $item?->$field }}</textarea>
@elseif($field==='status' && $module==='projets')<select class="form-select" name="status">@foreach(['planifie'=>'Planifié','en_cours'=>'En cours','suspendu'=>'Suspendu','termine'=>'Terminé'] as $value=>$name)<option value="{{ $value }}" @selected(($item?->status ?? 'planifie')===$value)>{{ $name }}</option>@endforeach</select>
@else<input class="form-control" id="{{ $field }}-{{ $item?->id ?? 'new' }}" name="{{ $field }}" type="{{ str_contains($field,'date') ? 'date' : ($field==='budget' ? 'number' : ($field==='website' ? 'url' : 'text')) }}" @if($field==='budget') step="0.01" min="0" @endif value="{{ $item?->$field instanceof \Carbon\CarbonInterface ? $item->$field->format('Y-m-d') : ($item?->$field ?? ($field==='currency'?'USD':'')) }}" @if(in_array($field,['name','slug','type','title','kind','status','currency'])) required @endif> >@endif</div>@endforeach
@if($module!=='actifs')<div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="published" value="1" @checked($item?->published ?? false)><span class="form-check-label">Publier sur le portail public</span></label></div>@endif</div>